import { line } from 'axylo';

/**
 * Options for the "Daily visits" line chart, shared by render() and by validate() checks.
 *
 * - `day` arrives as UTC midnights ('2026-03-01T00:00:00Z'). Declaring `type: 'date'` reads each one
 *   as its UTC calendar day, so the chart shows the same dates in every time zone (without it they
 *   would be instants, and viewers west of UTC would see every value one day early).
 * - `visits` are already numbers, so no `parse` is needed.
 * - Rows may come in any order; Axylo draws a line in x order.
 * - Days with no row (e.g. 6, 12 and 26 March) are left as gaps, not drawn as zero.
 */
export function visitsOptions(data) {
  return {
    title: 'Daily visits',
    data,
    x: { field: 'day', type: 'date' },
    y: { field: 'visits', label: 'Visits' },
  };
}

/**
 * Draws the daily visits line chart into `element` and returns the Axylo chart handle.
 * @param {HTMLElement} element the chart container
 * @param {ReadonlyArray<{ day: string, visits: number }>} data the rows from data.json
 */
export default function render(element, data) {
  return line(element, visitsOptions(data));
}

